import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';

export default {
  methods: {
    generateSavedColumns(key: string, defaultColumns: dynamicObj) {
      const savedColumns = this.getSavedColumnPreference(key);
      if (savedColumns) {
        let saved_columns = JSON.parse(savedColumns);
        if (defaultColumns.length !== saved_columns.length) {
          //if new default column is differ return the default
          return defaultColumns;
        }

        saved_columns = saved_columns.map((column: dynamicObj) => {
          const index = defaultColumns.findIndex(
            (columnDefault: dynamicObj) => column.name == columnDefault.name,
          );
          if (index != -1) {
            const foundColumn = defaultColumns[index];
            logInfo(foundColumn.label, 'label');
            return {
              ...column,
              label: foundColumn.translation_key
                ? foundColumn.translation_key
                : foundColumn.label,
            } as dynamicObj;
          } else {
            return column;
          }
        });

        return saved_columns as dynamicObj;
      } else {
        return defaultColumns;
      }
    },
    async getSavedColumnPreference(key: string) {
      const settings_store = useSettingStore();
      const saved_columns = await settings_store.getSetting(key) as dynamicObj;
      return String(!saved_columns ? '' : saved_columns);
    },
  },
};
